mad-bhaktā yānti mām api\"}}]}]]]}]\n"])self.__next_f.push([1,"2c:[\"$\",\"div\",\"2280-synonyms,2280-synonyms\",{\"className\":\"av-synonyms\",\"children\":[[\"$\",\"h2\",null,{\"className\":\"text-center em-leading-5 em-text-xl font-bold em-mb-4\",\"children\":\"Synonyms\"}],[[\"$\",\"$L29\",\"child-2283\",{\"child\":\"$23:props:children:0:props:children:props:page:child_items:2:children:0\",\"hasId\":true,\"children\":[\"$\",\"div\",null,{\"className\":\"em-mb-4 em-leading-8 em-text-base text-justify\",\"children\":[[\"$\",\"span\",\"wfwundefined-0\",{\"className\":\"inline\",\"children\":[[[\"$\",\"$L20\",\"wfwundefined-0-anta\",{\"href\":\"/en/search/synonyms/?original=anta\",\"children\":[\"$\",\"em\",null,{\"children\":\"anta\"}]}],\"-\",[\"$\",\"$L20\",\"wfwundefined-2-vat\",{\"href\":\"/en/search/synonyms/?original=vat\",\"children\":[\"$\",\"em\",null,{\"children\":\"vat\"}]}]],\" — \",[\"$\",\"span\",null,{\"className\":\"inline\",\"dangerouslySetInnerHTML\":{\"__html\":\"perishable\"}}],\"; \"]}],[\"$\",\"span\",\"wfwundefined-1\",{\"className\":\"inline\",\"children\":[[[\"$\",\"$L20\",\"wfwundefined-0-tu\",{\"href\":\"/en/search/synonyms/?original=tu\",\"children\":[\"$\",\"em\",null,{\"children\":\"tu\"}]}]],\" — \",[\"$\",\"span\",null,{\"className\":\"inline\",\"dangerouslySetInnerHTML\":{\"__html\":\"but\"}}],\"; \"]}],[\"$\",\"span\",\"wfwundefined-2\",{\"className\":\"inline\",\"children\":[[[\"$\",\"$L20\",\"wfwundefined-0-phalam\",{\"href\":\"/en/search/synonyms/?original=phalam\",\"children\":[\"$\",\"em\",null,{\"children\":\"phalam\"}]}]],\" — \",[\"$\",\"span\",null,{\"className\":\"inline\",\"dangerouslySetInnerHTML\":{\"__html\":\"fruit\"}}],\"; \"]}],[\"$\",\"span\",\"wfwundefined-3\",{\"className\":\"inline\",\"children\":[[[\"$\",\"$L20\",\"wfwundefined-0-teṣām\",{\"href\":\"/en/search/synonyms/?original=teṣām\",\"children\":[\"$\",\"em\",null,{\"children\":\"teṣām\"}]}]],\" — \",[\"$\",\"span\",null,{\"className\":\"inline\",\"dangerouslySetInnerHTML\":{\"__html\":\"their\"}}],\"; \"]}],[\"$\",\"span\",\"wfwundefined-4\",{\"className\":\"inline\",\"children\":[[[\"$\",\"$L20\",\"wfwundefined-0-tat\",{\"href\":\"/en/search/synonyms/?original=tat\",\"children\":[\"$\",\"em\",null,{\"children\":\"tat\"}]}]],\" — \",[\"$\",\"span\",null,{\"className\":\"inline\",\"dangerouslySetInnerHTML\":{\"__html\":\"that\"}}],\"; \"]}],[\"$\",\"span\",\"wfwundefined-5\",{\"className\":\"inline\",\"children\":[[[\"$\",\"$L20\",\"wfwundefined-0-bhavati\",{\"href\":\"/en/search/synonyms/?original=bhavati\",\"children\":[\"$\",\"em\",null,{\"children\":\"bhavati\"}]}]],\" — \",[\"$\",\"span\",null,{\"className\":\"inline\",\"dangerouslySetInnerHTML\":{\"__html\":\"becomes\"}}],\"; \"]}],[\"$\",\"span\",\"wfwundefined-6\",{\"className\":\"inline\",\"children\":[[[\"$\",\"$L20\",\"wfwundefined-0-alpa\",{\"href\":\"/en/search/synonyms/?original=alpa\",\"children\":[\"$\",\"em\",null,{\"children\":\"alpa\"}]}],\"-\",[\"$\",\"$L20\",\"wfwundefined-2-medhasām\",{\"href\":\"/en/search/synonyms/?original=medhasām\",\"children\":[\"$\",\"em\",null,{\"children\":\"medhasām\"}]}]],\" — \",[\"$\",\"span\",null,{\"className\":\"inline\",\"dangerouslySetInnerHTML\":{\"__html\":\"of those of small intelligence\"}}],\"; \"]}],[\"$\",\"span\",\"wfwundefined-7\",{\"className\":\"inline\",\"children\":[[[\"$\",\"$L20\",\"wfwundefined-0-devān\",{\"href\":\"/en/search/synonyms/?original=devān\",\"children\":[\"$\",\"em\",null,{\"children\":\"devān\"}]}]],\" — \",[\"$\",\"span\",null,{\"className\":\"inline\",\"dangerouslySetInnerHTML\":{\"__html\":\"to the demigods\"}}],\"; \"]}],[\"$\",\"span\",\"wfwundefined-8\",{\"className\":\"inline\",\"children\":[[[\"$\",\"$L20\",\"wfwundefined-0-deva\",{\"href\":\"/en/search/synonyms/?original=deva\",\"children\":[\"$\",\"em\",null,{\"children\":\"deva\"}]}],\"-\",[\"$\",\"$L20\",\"wfwundefined-2-yajaḥ\",{\"href\":\"/en/search/synonyms/?original=yajaḥ\",\"children\":[\"$\",\"em\",null,{\"children\":\"yajaḥ\"}]}]],\" — \",[\"$\",\"span\",null,{\"className\":\"inline\",\"dangerouslySetInnerHTML\":{\"__html\":\"the worshipers of the demigods\"}}],\"; \"]}],[\"$\",\"span\",\"wfwundefined-9\",{\"className\":\"inline\",\"children\":[[[\"$\",\"$L20\",\"wfwundefined-0-yānti\",{\"href\":\"/en/search/synonyms/?original=yānti\",\"children\":[\"$\",\"em\",null,{\"children\":\"yānti\"}]}]],\" — \",[\"$\",\"span\",null,{\"className\":\"inline\",\"dangerouslySetInnerHTML\":{\"__html\":\"go\"}}],\"; \"]}],[\"$\",\"span\",\"wfwundefined-10\",{\"className\":\"inline\",\"children\":[[[\"$\",\"$L20\",\"wfwundefined-0-mat\",{\"href\":\"/en/search/synonyms/?original=mat\",\"children\":[\"$\",\"em\",null,{\"children\":\"mat\"}]}]],\" — \",[\"$\",\"span\",null,{\"className\":\"inline\",\"dangerouslySetInnerHTML\":{\"__html\":\"My\"}}],\"; \"]}],[\"$\",\"span\",\"wfwundefined-11\",{\"className\":\"inline\",\"children\":[[[\"$\",\"$L20\",\"wfwundefined-0-bhaktāḥ\",{\"href\":\"/en/search/synonyms/?original=bhaktāḥ\",\"children\":[\"$\",\"em\",null,{\"children\":\"bhaktāḥ\"}]}]],\" — \",[\"$\",\"span\",null,{\"className\":\"inline\",\"dangerouslySetInnerHTML\":{\"__html\":\"devotees\"}}],\"; \"]}],[\"$\",\"span\",\"wfwundefined-12\",{\"className\":\"inline\",\"children\":[[[\"$\",\"$L20\",\"wfwundefined-0-yānti\",{\"href\":\"/en/search/synonyms/?original=yānti\",\"children\":[\"$\",\"em\",null,{\"children\":\"yānti\"}]}]],\" — \",[\"$\",\"span\",null,{\"className\":\"inline\",\"dangerouslySetInnerHTML\":{\"__html\":\"go\"}}],\"; \"]}],\"$L31\",\"$L32\"]}]}]]]}]\n"])self.__next_f.push([1,"2d:[\"$\",\"div\",\"2280-translation,2280-translation\",{\"className\":\"av-translation\",\"children\":[[\"$\",\"h2\",null,{\"className\":\"text-center em-leading-5 em-text-xl font-bold em-mb-4\",\"children\":\"Translation\"}],[[\"$\",\"$L29\",\"child-2284\",{\"child\":\"$23:props:children:0:props:children:props:page:child_items:3:children:0\",\"hasId\":true,\"children\":[\"$\",\"div\",null,{\"className\":\"em-mb-4 em-leading-8 em-text-base s-justify\",\"children\":[\"$\",\"strong\",null,{\"dangerouslySetInnerHTML\":{\"__html\":\"Men of small intelligence worship the demigods, and their fruits are limited and temporary. Those who worship the demigods go to the planets of the demigods, but My devotees ultimately reach My supreme planet.\"}}]}]}]]]}]\n"])self.__next_f.push([1,"2e:[\"$\",\"div\",\"2280-purport,2280-purport\",{\"className\":\"av-purport\",\"children\":[[\"$\",\"h2\",null,{\"className\":\"text-center em-leading-5 em-text-xl font-bold em-mb-4\",\"children\":\"Purport\"}],[[\"$\",\"$L29\",\"child-2285\",{\"child\":\"$23:props:children:0:props:children:props:page:child_items:4:children:0\",\"hasId\":true,\"children\":[\"$\",\"div\",null,{\"className\":\"em-mb-4 em-leading-8 em-text-base s-justify\",\"dangerouslySetInnerHTML\":{\"__html\":\"Some commentators on the Bhagavad-gītā say that one who worships a demigod can reach the Supreme Lord, but here it is clearly stated that the worshipers of demigods go to the different planetary systems where various demigods are situated, just as a worshiper of the sun achieves the sun or a worshiper of the demigod of the moon achieves the moon. Similarly, if anyone wants to worship a demigod like Indra, he can attain that particular god’s planet. It is not that everyone, regardless of whatever demigod is worshiped, will reach the Supreme Personality of Godhead. That is denied here, for it is clearly stated that the worshipers of demigods go to different planets in the material world but the devotee of the Supreme Lord goes directly to the supreme planet of the Personality of Godhead.\"}}]}],[\"$\",\"$L29\",\"child-2286\",{\"child\":\"$23:props:children:0:props:children:props:page:child_items:4:children:1\",\"hasId\":true,\"children\":[\"$\",\"div\",null,{\"className\":\"em-mb-4 em-leading-8 em-text-base s-justify\",\"dangerouslySetInnerHTML\":{\"__html\":\"Here the point may be raised that if the demigods are different parts of the body of the Supreme Lord, then the same end should be achieved by worshiping them. However, worshipers of the demigods are less intelligent because they don’t know to what part of the body food must be supplied. Some of them are so foolish that they claim that there are many parts and many ways to supply food. This isn’t very sanguine. Can anyone supply food to the body through the ears or eyes? They do not know that these demigods are different parts of the universal body of the Supreme Lord, and in their ignorance they believe that each and every demigod is a separate God and a competitor of the Supreme Lord.\"}}]}],[\"$\",\"$L29\",\"child-2287\",{\"child\":\"$23:props:children:0:props:children:props:page:child_items:4:children:2\",\"hasId\":true,\"children\":[\"$\",\"div\",null,{\"className\":\"em-mb-4 em-leading-8 em-text-base s-justify\",\"dangerouslySetInnerHTML\":{\"__html\":\"Not only are the demigods parts of the Supreme Lord, but ordinary living entities are also. In the Śrīmad-Bhāgavatam it is stated that the brāhmaṇas are the head of the Supreme Lord, the kṣatriyas are His arms, the vaiśyas are His waist, the śūdras are His legs, and all serve different functions. Regardless of the situation, if one knows that both the demigods and he himself are part and parcel of the Supreme Lord, his knowledge is perfect. But if he does not understand this, he achieves different planets where the demigods reside. This is not the same destination the devotee reaches.\"}}]}],[\"$\",\"$L29\",\"child-2288\",{\"child\":\"$23:props:children:0:props:children:props:page:child_items:4:children:3\",\"hasId\":true,\"children\":[\"$\",\"div\",null,{\"className\":\"em-mb-4 em-leading-8 em-text-base s-justify\",\"dangerouslySetInnerHTML\":{\"__html\":\"The results achieved by the demigods’ benedictions are perishable because within this material world the planets, the demigods and their worshipers are all perishable. Therefore it is clearly stated in this verse that all results achieved by worshiping demigods are perishable, and therefore such worship is performed by the less intelligent living entity. Because the pure devotee engaged in Kṛṣṇa consciousness in devotional service of the Supreme Lord achieves eternal blissful existence that is full of knowledge, his achievements and those of the common worshiper of the demigods are different. The Supreme Lord is unlimited; His favor is unlimited; His mercy is unlimited. Therefore the mercy of the Supreme Lord upon His pure devotees is unlimited.\"}}]}]]]}]\n"])self.__next_f.push([1,"33:[[\"$\",\"source\",null,{\"srcSet\":\"https://simpleanalyticsbadges.com/vedabase.io?mode=auto\",\"media\":\"(prefers-color-scheme: dark)\"}],[\"$\",\"img\",null,{\"src\":\"https://simpleanalyticsbadges.com/vedabase.io?mode=auto\",\"loading\":\"lazy\",\"referrerPolicy\":\"no-referrer\",\"crossOrigin\":\"anonymous\"}]]\n"])self.__next_f.push([1,"26:[\"$\",\"div\",null,{\"id\":\"footer\",\"className\":\"mt-auto w-full max-w-7xl mx-auto pt-3 mb-6 text-sm text-vb-normal-text/80 text-center\",\"children\":[[\"$\",\"$L1f\",null,{\"donors\":\"Shweta Saxena; Gopalakrishnan Soundarajan;    Kuldip Persaud;  Raghava Chandra Dasa; Shubhangi Rajiv Panjiyar; Suparna Kotaru;  Rajendra and Geeta Ramchandani;  Jaykumar Prabhakar; Bharat Vyas; Shri Chander Mohan Gilhotra, HG Prashant Mukund Das, Shri Trilok Singh Grover, HG Bhakta Mitra Das, Laxmi Narayan Agarwal; Ronak Talati; Bhargav Ashok; Akiralali; Rajasa das; Riya and Tejal Chopade; Indradyumna Swami; Jai Devaki Parks;  Ashmi Chakraborty; Hari-kirtana das; Ramesta das; Prasad Buddhavarapu; Kresna Sucandra; Esekiel Jaggernauth\",\"locale\":\"en\"}],[\"$\",\"div\",null,{\"className\":\"w-full max-w-screen-xl mx-auto text-vb-normal-text mb-3\",\"children\":[[\"$\",\"a\",null,{\"target\":\"_blank\",\"rel\":\"noopener noreferrer\",\"href\":\"https://t.me/online_vedabase\",\"className\":\"text-vb-normal-text hover:text-vb-normal-text/60\",\"alt\":\"Vedabase Telegr