māṁ tu veda na kaścana\"}}]}]]]}]\n"])self.__next_f.push([1,"2d:[\"$\",\"div\",\"2313-synonyms,2313-synonyms\",{\"className\":\"av-synonyms\",\"children\":[[\"$\",\"h2\",null,{\"className\":\"text-center em-leading-5 em-text-xl font-bold em-mb-4\",\"children\":\"Synonyms\"}],[[\"$\",\"$L2a\",\"child-2316\",{\"child\":\"$23:props:children:0:props:children:props:page:child_items:2:children:0\",\"hasId\":true,\"children\":[\"$\",\"div\",null,{\"className\":\"em-mb-4 em-leading-8 em-text-base text-justify\",\"children\":[[\"$\",\"span\",\"wfwundefined-0\",{\"className\":\"inline\",\"children\":[[[\"$\",\"$L20\",\"wfwundefined-0-veda\",{\"href\":\"/en/search/synonyms/?original=veda\",\"children\":[\"$\",\"em\",null,{\"children\":\"veda\"}]}]],\" — \",[\"$\",\"span\",null,{\"className\":\"inline\",\"dangerouslySetInnerHTML\":{\"__html\":\"know\"}}],\"; \"]}],[\"$\",\"span\",\"wfwundefined-1\",{\"className\":\"inline\",\"children\":[[[\"$\",\"$L20\",\"wfwundefined-0-aham\",{\"href\":\"/en/search/synonyms/?original=aham\",\"children\":[\"$\",\"em\",null,{\"children\":\"aham\"}]}]],\" — \",[\"$\",\"span\",null,{\"className\":\"inline\",\"dangerouslySetInnerHTML\":{\"__html\":\"I\"}}],\"; \"]}],[\"$\",\"span\",\"wfwundefined-2\",{\"className\":\"inline\",\"children\":[[[\"$\",\"$L20\",\"wfwundefined-0-samatītāni\",{\"href\":\"/en/search/synonyms/?original=samatītāni\",\"children\":[\"$\",\"em\",null,{\"children\":\"samatītāni\"}]}]],\" — \",[\"$\",\"span\",null,{\"className\":\"inline\",\"dangerouslySetInnerHTML\":{\"__html\":\"completely past\"}}],\"; \"]}],[\"$\",\"span\",\"wfwundefined-3\",{\"className\":\"inline\",\"children\":[[[\"$\",\"$L20\",\"wfwundefined-0-vartamānāni\",{\"href\":\"/en/search/synonyms/?original=vartamānāni\",\"children\":[\"$\",\"em\",null,{\"children\":\"vartamānāni\"}]}]],\" — \",[\"$\",\"span\",null,{\"className\":\"inline\",\"dangerouslySetInnerHTML\":{\"__html\":\"present\"}}],\"; \"]}],[\"$\",\"span\",\"wfwundefined-4\",{\"className\":\"inline\